class OrderService:
    def __init__(self):
        self.orders = []

    def create_order(self, price):
        total = calculate_total(price, 10) # Fixed: tax_rate now expected as percentage (e.g., 10 for 10%)
        order = {
            "price": price,
            "total": total
        }
        self.orders.append(order)
        return order
